  ('bf900ed7-d11c-507d-a911-489552f118d1', null, (select id from public.skills where slug = 'write-g12-precise-language'), null, 'hard',
   $q$A writer wants to stress how unusual a large turnout was by beginning with "Rarely." Which sentence is correctly formed and keeps a formal style?$q$, $q$[{"text":"Rarely, has the town seen such a large crowd at a chess tournament.","is_correct":false,"misconception_token":"unnecessary-comma"},{"text":"Rarely has the town seen such a large crowd at a chess tournament.","is_correct":true},{"text":"Rarely ever has the town seen such a big old crowd at a chess tournament.","is_correct":false,"misconception_token":"informal-word"},{"text":"Rarely the town has seen such a large crowd at a chess tournament.","is_correct":false,"misconception_token":"incorrect-inversion"}]$q$::jsonb, $q$Rarely has the town seen such a large crowd at a chess tournament.$q$, $q$When a sentence opens with a negative adverb like "Rarely," the helping verb comes before the subject: "has the town seen." "Rarely the town has seen" keeps normal word order, which sounds ungrammatical.$q$, 'draft', null)
